        self,
        segmentation_predictor: Any,
        depth_predictor: Any,
        cfg: dict | None = None,
        output_dir: str | Path | None = None,
        roi_classes: Sequence[int] | None = None,
        drivable_classes: Sequence[int] | None = None,
        quantiles: Sequence[float] | None = None,
    ) -> None:
